package com.example;

import org.eclipse.jface.text.IRegion;
import org.eclipse.jface.text.ITextViewer;
import org.eclipse.jface.text.ITextHoverExtension2;

// Dummy interface for a non-matching type
interface SomeOtherHover extends ITextHoverExtension2 {
    // Must have the method from ITextHoverExtension2
    @Override
    default Object getHoverInfo2(ITextViewer textViewer, IRegion hoverRegion) {
        return null;
    }
}

// Dummy BestMatchHover for compilation
class BestMatchHover implements ITextHoverExtension2 {
    @Override
    public Object getHoverInfo2(ITextViewer textViewer, IRegion hoverRegion) {
        return null;
    }
    public Object getHoverInfo2(ITextViewer textViewer, IRegion hoverRegion, boolean forInformationProvider) {
        return null;
    }
}

public class NegativeCases {

    private SomeOtherHover otherImpl = () -> null; // Receiver is not BestMatchHover
    private BestMatchHover bmHover = new BestMatchHover();

    public Object noMatchMethod(ITextViewer textViewer, IRegion subject) {
        // Should NOT match: receiver is not BestMatchHover
        otherImpl.getHoverInfo2(textViewer, subject);

        // Should NOT match: method already has 3 arguments
        return bmHover.getHoverInfo2(textViewer, subject, true);
    }
}
